"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def monitor_flag_rate(events):
    """The flag rate of a list of transcripts. See SPEC.md section 1."""
    if not events:
        return 0.0
    hits = sum(1 for e in events if e["flagged"] is True)
    return hits / len(events)


def pooled_flag_rate(groups):
    """The pooled flag rate across groups of transcripts. See SPEC.md section 2."""
    total = sum(len(events) for events in groups.values())
    if not total:
        return 0.0
    hits = sum(1 for events in groups.values() for e in events if e["flagged"] is True)
    return hits / total


def flags_in_window(daily_counts, days):
    """Sum over a trailing window of daily counts. See SPEC.md section 3."""
    return sum(daily_counts[-days:]) if days > 0 else 0


def flag_rate_by_group(groups):
    """The flag rate of each group. See SPEC.md section 9."""
    return {
        name: monitor_flag_rate(groups[name]) if groups[name] else None
        for name in sorted(groups)
    }


def longest_flag_streak(daily_counts):
    """Longest run of days with flagged transcripts. See SPEC.md section 10."""
    best = cur = 0
    for c in daily_counts:
        if c > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    out = []
    for line_number, line in enumerate(lines, 1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected three fields")
        id_, day, flag = fields
        try:
            day = int(day)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: invalid day") from exc
        flags = {"1": True, "0": False, "": None}
        if flag not in flags:
            raise ValueError(f"line {line_number}: invalid flagged value")
        out.append({"id": id_, "day": day, "flagged": flags[flag]})
    return out


def dedupe_transcripts(events):
    """Remove duplicate transcripts. See SPEC.md section 5."""
    seen = {}
    for e in events:
        seen[e["id"]] = e
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Daily counts of flagged transcripts. See SPEC.md section 6."""
    if end_day < start_day:
        return []
    counts = [0] * (end_day - start_day + 1)
    for e in events:
        if e["flagged"] is True and start_day <= e["day"] <= end_day:
            counts[e["day"] - start_day] += 1
    return counts

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_none_counts_in_denominator():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}, {"flagged": False}]) == 1 / 3
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_each_transcript_and_handles_empty_groups():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 3), (2, 5), (3, 6), (10, 6)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected
    assert flags_in_window([], days) == 0


def test_parse_transcript_log_values_and_skipped_lines():
    lines = ["  # comment,with,commas", "", "  \t ", " a , 3 , 1 ", "b, -1, 0", "c, 0, "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 3, "flagged": True},
        {"id": "b", "day": -1, "flagged": False},
        {"id": "c", "day": 0, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,not-a-day,1", "a,1,yes"])
def test_parse_errors_report_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# comment", " ", "a,1,1", bad_line])


def test_dedupe_transcripts_keeps_last_duplicate_and_sorts_by_day_then_id():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "c", "day": 2, "flagged": True},
        {"id": "b", "day": 2, "flagged": None},
        {"id": "a", "day": 2, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[3], events[2], events[1]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_gaps_and_outside():
    events = [
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": None},
        {"day": 3, "flagged": False},
        {"day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_monitor_summary_uses_calendar_days_weighted_rate_and_nonempty_groups():
    groups = {
        "a": [{"day": 1, "flagged": True}],
        "b": [{"day": 4, "flagged": True}, {"day": 4, "flagged": False}],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 10) == {"rate": 0.667, "recent": 2, "groups": 2}
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [{"flagged": True}], "empty": [], "a": [{"flagged": True}], "b": [{"flagged": False}]}
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_includes_empty_and_orders_names():
    groups = {"z": [], "b": [{"flagged": None}], "a": [{"flagged": True}]}
    result = flag_rate_by_group(groups)
    assert result == {"a": 1.0, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]


def test_longest_flag_streak_resets_on_zero_and_negative():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4, 5, 6]) == 3
    assert longest_flag_streak([0, -2, 0]) == 0
    assert longest_flag_streak([]) == 0
